(* [comment removed for export] *)
Definition g_foot (BX1 : list (Z * Z)) (a : Z) : Prop :=
  (spc <= a < sp) \/ (F <= a < F + B - 8 /\ ~ (F + 24 <= a < F + 32)) \/ (F / 8 + SB <= a < F / 8 + SB + B / 8)
  \/ in_block BX1 a \/ (~ L5.outside W a /\ aclientw L ar LBX FF 0 0 a /\ ~ (0x10000 <= a < 0x6b6000)).
Lemma g_piece BX1 M1 model1 LK1 Aw1 cr1 (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) (Wp : Z -> Prop) :
  g_mem BX1 M1 model1 LK1 Aw1 cr1 ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  (forall a, Wp a -> ~ ocell a /\ g_foot BX1 a) ->
  (forall (M3 : mem) model3,
