Lemma g_callee_entry BX1 M1 model1 LK1 Aw1 cr1 R1 (ra hc : Z) :
  g_mem BX1 M1 model1 LK1 Aw1 cr1 -> 0 <= hc -> hc + 1 <= h ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  PMSPA.entryA AD L ar R1 M1 spc ra hc /\ PGSA.ffroomB PQRA.FCM hc FF' LK1 /\ PMSPA.ffrsA FF' spc /\ spc mod 16 = 0.
