(* [comment removed for export] *)
Lemma g_after (W1 : list L5.range) BX1 BXa BX4 M1 model1 LK1 Aw1 cr1 (M4 : mem) model4 LK4 Aw4 cr4 (hc : Z) (Wc : list L5.range) :
  g_mem BX1 M1 model1 LK1 Aw1 cr1 -> 0 <= hc -> hc + 1 <= h ->
  L5CA.ahpres L ar (BXa ++ LBX) FF' spc (PMSPA.pm_scr hc) Wc M1 M4 ->
  ri_inv HI (BX4 ++ LBX) FF' LK4 cr4 Aw4 M4 (vml_of model4) -> L5CA.amodel_ok Aw4 model4 -> model_rt model1 model4 -> incl Aw1 Aw4 -> incl LK4 LK1 ->
  (forall rr a, In rr Wc -> L5.in_rng rr a -> ~ (spc <= a < sp) /\ ~ (F / 8 + SB <= a < F / 8 + SB + B / 8)) ->
  (forall a, aclient L ar LBX FF sp SCR a -> L5.outside W a -> L5.outside Wc a) ->
  g_mem BX4 M4 model4 LK4 Aw4 cr4
  /\ (forall a, spc <= a < sp -> M4 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a))
