(* [comment removed for export] *)
Lemma g_fin BX5 M5 model5 LK5 Aw5 cr5 (fx5 fx9 : FPState) R5 R9 (pc5 : Z) (M9v : mem) :
  g_mem BX5 M5 model5 LK5 Aw5 cr5 ->
  msteps RSEGS (st fx5 R5 pc5 (mrestrict (ahid Aw5 model5) M5)) (st fx9 R9 r M9v) ->
  mem_grows (mrestrict (ahid Aw5 model5) M5) M9v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ PQAKUF.WretX F fl k (fun _ => False) a -> M9v (Z_to_bv 64 a) = mrestrict (ahid Aw5 model5) M5 (Z_to_bv 64 a)) ->
  L5.u8_at RSEGS M9v fl 0 ->
  (forall (Mf : mem) (modelf : Model),
      L5SAR.ek L ar (BX5 ++ LBX) FF 0 0 [] M5 Mf ->
      L5CA.ahpres L ar LBX FF sp SCR W M Mf ->
      model_rt model modelf -> incl LK5 LK -> incl Aw Aw5 -> L5CA.amodel_ok Aw5 modelf ->
      ri_inv HI (BX5 ++ LBX) FF LK5 cr5 Aw5 Mf (vml_of modelf) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx9 R9 r Mf modelf) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
