Definition opdelU_specF (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (q n sp r : Z) (D : list (list Z)) (Kt : list Z),
    ri_inv (HIk D) LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    In (q, n) LB -> getr R 10%bv = Z_to_bv 64 q ->
    getr R 1%bv = Z_to_bv 64 r -> L5.ra_ok r ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 4%bv = Z_to_bv 64 (hl_tp L) -> L5CA.astk ar M sp PMSPA.OPDEL_SCR ->
    HAR.ukey_at L ar (HAR.hlr_pc_free LR) R M Kt ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (Aw' : list (Z * Z)),
        regs_preserved R R' ->
        L5CA.ahpres L ar (lb_remove q LB) FF sp PMSPA.OPDEL_SCR [] M M' ->
        model_rt model model' -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv (HIk (Kt :: D)) (lb_remove q LB) FF LK (if HAR.warm_ok Kt D n then (fst cr + 1, snd cr) else cr) Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
End Specs.

