Lemma opdelU_at (pc : Z) :
  (forall fx R M, msteps RSEGS (st fx R pc M) (st fx R 0x8073c M)) -> opdelU_specF RSEGS L ar HIk LR pc.
Proof.
  intros JMP fx R M model K LB FF LK A cr q n sp r D Kt HH AM HK INQ G10 G1 RA G2 G4 STK UK KONT.
  pose proof STK as (A16 & SLO & SHI & SPT & DSCR & DUP). unfold PMSPA.OPDEL_SCR, PMSPA.MALLOC_SCR in SLO, DSCR.
  apply (apiece_ro L ar C (HIk D) LYa (HIokF D) LB FF LK cr A M model fx fx R pc R 0x8073c (mrestrict (ahid A model) M) K HH AM (JMP fx R _) (mem_grows_refl _)).
  { intros a Ha. reflexivity. }
  intros M1 model1 HH1 AM1 RT1 AH1 VIS1 MGM1 FRM1.
  assert (E1 : M1 = M) by (apply mem_eq_of_agree; exact FRM1). subst M1.
  pose proof (HAR.afreeU_holds L ar C SCFG LR HIk FAMok) as HF. unfold HAR.afreeU_spec, HAR.afree_preG, HAR.afree_postG, HAR.ukey_at in HF. unfold HAR.ukey_at in UK.
