  assert (U2 : bv_unsigned (getr R 2%bv) = sp). { rewrite G2. apply L5.unsigned_lit. clear - SLO SHI SPT; lia. }
  eapply (HF D fx R M model1 LB FF LK cr A q n K Kt); clear HF.
  - split; [exact HH1|]. split; [exact (proj1 AM1)|]. split; [exact (proj2 AM1)|]. split; [exact INQ|]. split; [exact G10|]. split; [exact G4|].
    split. { rewrite G1. apply Hoare.ret_ok_even. rewrite L5.unsigned_lit by (destruct RA as [X _]; clear - X; lia). exact (proj2 RA). }
