    rewrite U2. pose proof (astack_ok_of_astk L ar C LYa M M sp PMSPA.OPDEL_SCR 0 4096 STK (mem_grows_refl M)) as X.
    replace (sp - 0) with sp in X by (clear; lia). apply X. clear; lia. clear; lia. unfold PMSPA.OPDEL_SCR, PMSPA.MALLOC_SCR; clear; lia. exact A16.
  - exact UK.
  - intros R' M' model' A' RP PRES RT2 IA MI2 HH2. rewrite U2 in PRES. rewrite G1.
    apply (KONT fx R' M' model' A' RP).
    + split. { intros a (Ha & Hc & _). apply (proj1 PRES). exact Ha. exact Hc. }
      split. { intros i Hi. apply (proj2 PRES). unfold PMSPA.OPDEL_SCR, PMSPA.MALLOC_SCR in *. clear - Hi; lia. }
