      rewrite (proj1 PRES a Ha). exact HM. exact Hc.
    + eapply L5LZ.model_rt_trans. exact RT1. exact RT2.
    + exact IA.
    + split. rewrite (L5LZ.model_rt_halted _ _ RT2). exact (proj1 AM1). exact MI2.
    + exact HH2.
Qed.

